INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `lang0`, `Probability0`, `em0_0`, `em0_1`) VALUES
(976000, 'Klm, kmmrg, mnlmur. Mr fl frglmur mmurgrgl glg flku mm bu mrrlugl.', 'Klm, kmmrg, mnlmur. Mr fl frglmur mmurgrgl glg flku mm bu mrrlugl.', 0, 1, 0, 1),
(976001, 'Fl\'mrg mrgr bu. Fl\'mrg mmrlmrf bu. Fl\'mrg mm mmr hmmrlmrrk ng ffr flm hmrglmmmurnl.', 'Fl\'mrg mrgr bu. Fl\'mrg mmrlmrf bu. Fl\'mrg mm mmr hmmrlmrrk ng ffr flm hmrglmmmurnl.', 0, 1, 0, 1),
(976002, 'Mmrklgrglmm mrgl glgk fl gf fr gffrg. Mmrklgrglmm.', 'Mmrklgrglmm mrgl glgk fl gf fr gffrg. Mmrklgrglmm.', 0, 1, 0, 1),
(976003, 'Aglu grfrlgl. Furflm grfrlgl. Mrgk grfrlgl, glg glgk mrglu amr muuafrgm mrgs gluglm.', 'Aglu grfrlgl. Furflm grfrlgl. Mrgk grfrlgl, glg glgk mrglu amr muuafrgm mrgs gluglm.', 0, 1, 0, 1),
(976004, 'Furg frgl glgk ffffr rgl amrglug glr. Rkuagll ng aafl. Mrg ng rgfrg.', 'Furg frgl glgk ffffr rgl amrglug glr. Rkuagll ng aafl. Mrg ng rgfrg.', 0, 1, 0, 1),
(976005, 'Mrgk gffrl, srrllg aff, ffrlg fugrg. Mrfr mm mmrgf glg flku rgfrg bu mmrkurg.', 'Mrgk gffrl, srrllg aff, ffrlg fugrg. Mrfr mm mmrgf glg flku rgfrg bu mmrkurg.', 0, 1, 0, 1),
(976006, 'Na mgrrrl mrgl fr flmn mmgr frglug. Na flmn mrgl fr mgrrrl mrglgl mrfrfl. Mrgknna.', 'Na mgrrrl mrgl fr flmn mmgr frglug. Na flmn mrgl fr mgrrrl mrglgl mrfrfl. Mrgknna.', 0, 1, 0, 1),
(976007, 'Mrfr rmmrgl. Mrfr rmmr glmrlu. Mrfr mrmrrglm ffl. Mrlmugl.', 'Mrfr rmmrgl. Mrfr rmmr glmrlu. Mrfr mrmrrglm ffl. Mrlmugl.', 0, 1, 0, 1),
(976008, 'Mr mrkm-kmrg shrlr mugshr glgk kugll. Rrg glgk kugll frgmrg. Rrg glgk frglm bm.', 'Mr mrkm-kmrg shrlr mugshr glgk kugll. Rrg glgk kugll frgmrg. Rrg glgk frglm bm.', 0, 1, 0, 1),
