(976010, 'Mr mrgrrrlk glgk glkmng. Mr glkmng mmmrmurr. Burglknn mnna mrfrfl. Aaurgr.', 'Mr mrgrrrlk glgk glkmng. Mr glkmng mmmrmurr. Burglknn mnna mrfrfl. Aaurgr.', 0, 1, 0, 1),
(976011, 'Mmrnag bu. Mmmr ffrf bu. Burglknn akmrg mrrglug bu. Mrglmmm.', 'Mmrnag bu. Mmmr ffrf bu. Burglknn akmrg mrrglug bu. Mrglmmm.', 0, 1, 0, 1),
(976012, 'Mr mrmmrgmrg mrgl mrgs. Frgk glm flku mmmr ng rff mrluglmm?', 'Mr mrmmrgmrg mrgl mrgs. Frgk glm flku mmmr ng rff mrluglmm?', 0, 1, 0, 1),
(976013, 'Mrgl. Mrgs gluglm.', 'Mrgl. Mrgs gluglm.', 0, 1, 0, 1),
(976014, 'Mrgl mrglglm mur mrgl fr mrglglm mur ffrf mrgrmu. Mmrgl glgk flufrg amr. Glgluuglmrg glgk flufrg amr.', 'Mrgl mrglglm mur mrgl fr mrglglm mur ffrf mrgrmu. Mmrgl glgk flufrg amr. Glgluuglmrg glgk flufrg amr.', 0, 1, 0, 1),
(976015, 'Terro-Rini, Shando Dor. Anu Tal Anu Shar Anu Shano.', 'Terro-Rini, Shando Dor. Anu Tal Anu Shar Anu Shano.', 0, 1, 0, 1),
(976016, 'Fu! So Smadda Flimeff! Duti, Duti, Wassa Weh Riva Sca Dim.', 'Fu! So Smadda Flimeff! Duti, Duti, Wassa Weh Riva Sca Dim.', 0, 1, 0, 1),
