(976020, 'Mr amrlm hrkmmn flglm rglgm mrngk mmmrg rgl aaflua. Mnlm. Flmrrr. Mr mrkm\'mrg. Mr\'mmmr amrgl mrlglm.', 'Mr amrlm hrkmmn flglm rglgm mrngk mmmrg rgl aaflua. Mnlm. Flmrrr. Mr mrkm\'mrg. Mr\'mmmr amrgl mrlglm.', 0, 1, 0, 1),
