INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(976054, 0, 0, 'Goth, Gloin. Goth Lo Ash Goth.', 12, 0, 100, 36, 0, 0, 0, 0, 'mod-murloc-naga'),
(976055, 0, 0, 'Bur Borne. Bur Borne.', 12, 0, 100, 0, 0, 3438, 0, 0, 'mod-murloc-naga'),
(976125, 0, 0, 'Anu! No Anu Al\'shar! Dor Dor Diel Belore!', 14, 0, 100, 0, 0, 6007, 0, 0, 'mod-murloc-naga'),
(976127, 0, 0, 'Anar Da Anu Shano, Thera! No Thoribas Anu!', 14, 0, 100, 0, 0, 6007, 0, 0, 'mod-murloc-naga'),
(976146, 0, 0, 'Gol. Gol, Gloin.', 12, 0, 100, 15, 0, 3437, 0, 0, 'mod-murloc-naga'),
(976152, 0, 0, 'Garde! Goth Lo Agol Engoth! Garde!', 14, 0, 100, 15, 0, 0, 0, 0, 'mod-murloc-naga'),
(976153, 0, 0, 'Ti Odes... Ti Odes!', 14, 0, 100, 15, 0, 11691, 0, 0, 'mod-murloc-naga'),
(976153, 1, 0, 'Majis! Majis, Nud Ve Nud! E Lo Agol Vrum!', 14, 0, 100, 15, 0, 11695, 0, 0, 'mod-murloc-naga'),
(976162, 0, 0, 'Odes Dana, Skilde Ver... Dana, Lo Ash Wirsh...', 14, 0, 100, 0, 0, 4025, 0, 0, 'mod-murloc-naga'),
(976163, 0, 0, 'Ti Dana! Vil Kaelsig Ti Dana?', 14, 0, 100, 15, 0, 4025, 0, 0, 'mod-murloc-naga'),
(976218, 0, 0, 'Ti Ador! Vil Bur Ti Ador? Vil Bur Lars?', 14, 0, 100, 22, 0, 5976, 0, 0, 'mod-murloc-naga'),
(976222, 0, 0, 'O Agol-Ver! O Odes Ver! Gol Nagan Uden Nandige An!', 12, 0, 100, 0, 0, 11821, 0, 0, 'mod-murloc-naga'),
(976224, 0, 0, 'Odes! Goth Lo Ash Wirsh, Vohl-Odes! Hir Ver Veld Skilde!', 14, 0, 100, 0, 0, 5979, 0, 0, 'mod-murloc-naga'),
